 76 │ /// An ephemeral loopback port: bind to port 0, read back what the OS
 77 │ /// assigned, release it immediately. The gap between release and the real
 78 │ /// server binding it is a bounded TOCTOU risk, acceptable for test
 79 │ /// infrastructure that owns the box.
 80 │ fn free_loopback_port() -> u16 {
 81 │     let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("loopback listener must bind");
 82 │     listener
 83 │         .local_addr()
 84 │         .expect("listener must have a local address")
 85 │         .port()
 86 │ }
