 88 │ /// A spawned server process, killed on drop so a panicking assertion never
 89 │ /// leaks it past the test. `log_path` is its combined stdout+stderr, written
 90 │ /// to a file rather than piped so a chatty server can never fill an
 91 │ /// undrained pipe and deadlock the test.
 92 │ struct ServerGuard {
 93 │     child: Child,
 94 │     log_path: PathBuf,
 95 │ }
 96 │ 
 97 │ impl ServerGuard {
 98 │     fn log(&self) -> String {
 99 │         fs::read_to_string(&self.log_path).unwrap_or_default()
100 │     }
101 │ }
