110 │ /// Redirects a spawned command's stdout and stderr to one combined log file
111 │ /// under `dir`/`name`, so a startup crash is diagnosable instead of silent.
112 │ fn log_to_file(command: &mut Command, dir: &Path, name: &str) -> PathBuf {
113 │     let log_path = dir.join(name);
114 │     let file = fs::File::create(&log_path).expect("server log file must be creatable");
115 │     let file_for_stderr = file.try_clone().expect("log file handle must be cloneable");
116 │     command.stdin(Stdio::null()).stdout(file).stderr(file_for_stderr);
117 │     log_path
118 │ }
