120 │ /// Blocks until `port` accepts a loopback TCP connection, or panics after
121 │ /// `timeout` -- including the server's captured output in the panic message
122 │ /// either way, and its exit status if it already died. Checking `try_wait`
123 │ /// first means a server that crashes at startup fails fast with its real
124 │ /// error instead of spinning out the whole timeout with no evidence.
125 │ fn wait_for_port(guard: &mut ServerGuard, port: u16, timeout: Duration) {
126 │     let deadline = Instant::now() + timeout;
127 │     loop {
128 │         if TcpStream::connect(("127.0.0.1", port)).is_ok() {
129 │             return;
130 │         }
131 │         if let Ok(Some(status)) = guard.child.try_wait() {
132 │             panic!(
133 │                 "server exited with {status} before binding 127.0.0.1:{port}; output:\n{}",
134 │                 guard.log()
135 │             );
136 │         }
137 │         if Instant::now() >= deadline {
138 │             panic!(
139 │                 "server on 127.0.0.1:{port} never became reachable within {timeout:?}; output:\n{}",
140 │                 guard.log()
141 │             );
142 │         }
143 │         std::thread::sleep(Duration::from_millis(100));
144 │     }
145 │ }
