112	110 │ /// Redirects a spawned command's stdout and stderr to one combined log file
113	111 │ /// under `dir`/`name`, so a startup crash is diagnosable instead of silent.
114	112 │ fn log_to_file(command: &mut Command, dir: &Path, name: &str) -> PathBuf {
115	113 │     let log_path = dir.join(name);
