122	120 │ /// Blocks until `port` accepts a loopback TCP connection, or panics after
123	121 │ /// `timeout` -- including the server's captured output in the panic message
124	122 │ /// either way, and its exit status if it already died. Checking `try_wait`
125	123 │ /// first means a server that crashes at startup fails fast with its real
126	124 │ /// error instead of spinning out the whole timeout with no evidence.
127	125 │ fn wait_for_port(guard: &mut ServerGuard, port: u16, timeout: Duration) {
128	126 │     let deadline = Instant::now() + timeout;
129	127 │     loop {
130	128 │         if TcpStream::connect(("127.0.0.1", port)).is_ok() {
131	129 │             return;
132	130 │         }
133	131 │         if let Ok(Some(status)) = guard.child.try_wait() {
134	132 │             panic!(
135	133 │                 "server exited with {status} before binding 127.0.0.1:{port}; output:\n{}",
136	134 │                 guard.log()
137	135 │             );
138	136 │         }
139	137 │         if Instant::now() >= deadline {
140	138 │             panic!(
141	139 │                 "server on 127.0.0.1:{port} never became reachable within {timeout:?}; output:\n{}",
142	140 │                 guard.log()
143	141 │             );
144	142 │         }
145	143 │         std::thread::sleep(Duration::from_millis(100));
146	144 │     }
147	145 │ }
