373 │ /// Starts a real local `pypiserver` on an ephemeral loopback port with
374 │ /// authentication fully disabled (`-a . -P .`, its own documented way to
375 │ /// allow anonymous browsing and uploads) and `--disable-fallback`, so a
376 │ /// lookup for an unknown project 404s instead of proxying to real PyPI.
377 │ ///
378 │ /// `--server gunicorn`: pypiserver's default `auto` backend selection falls
379 │ /// through to `wsgiref` when nothing else is installed, and `wsgiref`
380 │ /// (like `paste` and gevent's `pywsgi`, also measured) resolves the bind
381 │ /// address via `socket.getfqdn()` before it starts listening -- a reverse
382 │ /// DNS lookup that measured 12-35s on a real machine exhibiting the same
383 │ /// symptom as the CI macOS runner, against sub-second on Linux. `gunicorn`
384 │ /// has no such call anywhere in its source (grepped) and measured
385 │ /// consistently under 1s across repeated runs here; it forks a worker and
386 │ /// terminates both master and worker cleanly on the one SIGTERM `ServerGuard`
387 │ /// sends the master PID.
388 │ fn start_pypiserver(external: &Path) -> (ServerGuard, u16) {
389 │     let packages_dir = external.join("pypiserver-packages");
390 │     fs::create_dir_all(&packages_dir).unwrap();
391 │     let port = free_loopback_port();
392 │     let mut command = Command::new("pypi-server");
393 │     command.args([
394 │         "run",
395 │         "--server",
396 │         "gunicorn",
397 │         "--host",
398 │         "127.0.0.1",
399 │         "--port",
400 │         &port.to_string(),
401 │         "--authenticate",
402 │         ".",
403 │         "--passwords",
404 │         ".",
405 │         "--disable-fallback",
406 │         packages_dir.to_str().unwrap(),
407 │     ]);
408 │     let log_path = log_to_file(&mut command, external, "pypiserver.log");
409 │     let child = command.spawn().expect("pypi-server must be spawnable");
410 │     let mut guard = ServerGuard { child, log_path };
411 │     wait_for_port(&mut guard, port, Duration::from_secs(20));
412 │     (guard, port)
413 │ }
