        .files
        .iter()
        .filter(|file| pypi_simple_file_matches(file, version));
    let mut matched = false;
    for file in matching {
        if file.is_yanked() {
            return settled(ProviderObservationV1::Absent);
        }
        matched = true;
    }
    if !matched {
        return settled(ProviderObservationV1::Absent);
    }
    settled(exact_version(version))
}

